{"code":"import pandas as pd
import numpy as np

raw = pd.read_csv('raw_responses.csv')
pipeline = pd.read_csv('pipeline_output.csv')

# Let's write our own scorer in python and compare column by column.

def get_valid_ans(val):
    if pd.isna(val):
        return None
    try:
        iv = int(val)
    except:
        return None
    if iv in [0, 1, 2, 3]:
        return iv
    return None

def score_phq9(row):
    items = [f'phq9_{i}' for i in range(1, 10)]
    vals = []
    skipped = 0
    for it in items:
        v = get_valid_ans(row[it])
        if v is None:
            skipped += 1
        else:
            vals.append(v)

    # self harm flag
    # Question 9 is phq9_9. Any answer other than 0 (1, 2, 3) -> True. 0 -> False. Skipped -> None/NaN
    v9 = get_valid_ans(row['phq9_9'])
    if v9 is None:
        sh_flag = None
    elif v9 > 0:
        sh_flag = True
    else:
        sh_flag = False

    if skipped >= 2:
        return np.nan, np.nan, np.nan, sh_flag
    elif skipped == 1:
        # scale up: sum * 9 / 8, round to whole, halves round up
        s = sum(vals)
        raw_scaled = s * 9.0 / 8.0
        # rounding: decimal 0.5 rounds up
        from decimal import Decimal, ROUND_HALF_UP
        total = int(Decimal(str(raw_scaled)).quantize(Decimal('1'), rounding=ROUND_HALF_UP))
        prorated = True
    else:
        total = sum(vals)
        prorated = False

    # band
    if pd.isna(total):
        band = np.nan
    else:
        if total <= 4:
            band = 'none-minimal'
        elif total <= 9:
            band = 'mild'
        elif total <= 14:
            band = 'moderate'
        elif total <= 19:
            band = 'moderately severe'
        else:
            band = 'severe'

    return float(total), band, prorated, sh_flag

def score_gad7(row):
    items = [f'gad7_{i}' for i in range(1, 8)]
    vals = []
    skipped = 0
    for it in items:
        v = get_valid_ans(row[it])
        if v is None:
            skipped += 1
        else:
            vals.append(v)

    if skipped >= 2:
        return np.nan, np.nan, np.nan
    elif skipped == 1:
        s = sum(vals)
        raw_scaled = s * 7.0 / 6.0
        from decimal import Decimal, ROUND_HALF_UP
        total = int(Decimal(str(raw_scaled)).quantize(Decimal('1'), rounding=ROUND_HALF_UP))
        prorated = True
    else:
        total = sum(vals)
        prorated = False

    if pd.isna(total):
        band = np.nan
    else:
        if total <= 4:
            band = 'minimal'
        elif total <= 9:
            band = 'mild'
        elif total <= 14:
            band = 'moderate'
        else:
            band = 'severe'

    return float(total), band, prorated

def score_rses(row):
    items = [f'rses_{i}' for i in range(1, 11)]
    # negative items: 3, 5, 8, 9, 10
    neg_items = {3, 5, 8, 9, 10}
    vals = []
    skipped = 0
    for i in range(1, 11):
        it = f'rses_{i}'
        v = get_valid_ans(row[it])
        if v is None:
            skipped += 1
        else:
            if i in neg_items:
                vals.append(3 - v)
            else:
                vals.append(v)

    if skipped >= 2:
        return np.nan, np.nan
    elif skipped == 1:
        s = sum(vals)
        raw_scaled = s * 10.0 / 9.0
        from decimal import Decimal, ROUND_HALF_UP
        total = int(Decimal(str(raw_scaled)).quantize(Decimal('1'), rounding=ROUND_HALF_UP))
        prorated = True
    else:
        total = sum(vals)
        prorated = False

    return float(total) if not pd.isna(total) else np.nan, prorated

my_results = []
for idx, row in raw.iterrows():
    p_tot, p_band, p_pro, p_sh = score_phq9(row)
    g_tot, g_band, g_pro = score_gad7(row)
    r_tot, r_pro = score_rses(row)
    my_results.append({
        'respondent_id': row['respondent_id'],
        'phq9_total': p_tot,
        'phq9_band': p_band,
        'phq9_prorated': p_pro,
        'phq9_self_harm_flag': p_sh,
        'gad7_total': g_tot,
        'gad7_band': g_band,
        'gad7_prorated': g_pro,
        'rses_total': r_tot,
        'rses_prorated': r_pro
    })

df_my = pd.DataFrame(my_results)

# Compare with pipeline
for col in pipeline.columns:
    if col == 'respondent_id':
        continue
    # compare values considering NaN
    eq = (pipeline[col].values == df_my[col].values) | (pd.isna(pipeline[col]) & pd.isna(df_my[col]))
    mismatches = ~eq
    n_mismatch = mismatches.sum()
    print(f"Column {col}: {n_mismatch} mismatches")
    if n_mismatch > 0:
        bad_idx = np.where(mismatches)[0]
        print(f"  Example mismatch at row {bad_idx[0]} (ID {raw.loc[bad_idx[0], 'respondent_id']}): pipeline={pipeline.loc[bad_idx[0], col]}, mine={df_my.loc[bad_idx[0], col]}")
"}

