raw = pd.read_csv('raw_responses.csv')
pipeline = pd.read_csv('pipeline_output.csv')

# Test hypothesis: phq9_self_harm_flag is computed from phq9_8 instead of phq9_9
def get_flag_from_phq9_8(val):
    if pd.isna(val) or val == -9:
        return np.nan
    try:
        iv = int(val)
    except:
        return np.nan
    if iv in [1, 2, 3]:
        return True
    elif iv == 0:
        return False
    return np.nan

expected_flag = raw['phq9_8'].apply(get_flag_from_phq9_8)
# Handle boolean vs object / float comparison in pandas
eq = (pipeline['phq9_self_harm_flag'] == expected_flag) | (pipeline['phq9_self_harm_flag'].isna() & expected_flag.isna())
print("Exact match with phq9_8 based flag:", eq.all())
print("Number of matches:", eq.sum())
